<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login(); $pdo=db(); $message=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post_string('action');try{
if($action==='add'){$first=post_string('first_name');$last=post_string('last_name');if($first===''||$last==='')throw new RuntimeException('First and last name are required.');$code='CL-'.date('YmdHis').'-'.random_int(100,999);$st=$pdo->prepare('INSERT INTO clients(client_code,first_name,last_name,email,phone,status,created_by) VALUES(?,?,?,?,?,"active",?)');$st->execute([$code,$first,$last,post_string('email')?:null,post_string('phone')?:null,current_user()['id']]);$id=(int)$pdo->lastInsertId();activity($pdo,'create','clients',$id,'Client created: '.$first.' '.$last);flash('success','Client created successfully.');}
if($action==='archive'){$id=post_int('id');$pdo->prepare('UPDATE clients SET deleted_at=NOW(),status="archived" WHERE id=?')->execute([$id]);activity($pdo,'archive','clients',$id,'Client archived');flash('success','Client archived.');}
}catch(Throwable $e){error_log('[SPS CLIENTS] '.$e->getMessage());flash('success',$e->getMessage());}redirect('clients.php');}
$search=trim((string)($_GET['q']??''));if($search!==''){$st=$pdo->prepare('SELECT * FROM clients WHERE deleted_at IS NULL AND (first_name LIKE ? OR last_name LIKE ? OR email LIKE ? OR client_code LIKE ?) ORDER BY id DESC LIMIT 200');$like="%$search%";$st->execute([$like,$like,$like,$like]);$clients=$st->fetchAll();}else{$clients=$pdo->query('SELECT * FROM clients WHERE deleted_at IS NULL ORDER BY id DESC LIMIT 200')->fetchAll();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clients · SPS CRM</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font-family:Arial}.top{height:68px;background:#fff;border-bottom:1px solid #e6ebf2;padding:0 26px;display:flex;align-items:center;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1250px;margin:auto;padding:28px}.bar{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:18px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:16px;padding:20px}.search{display:flex;gap:8px;margin-bottom:14px}.input,.field input{padding:11px 12px;border:1px solid #d8dfeb;border-radius:9px;width:100%;background:#fff}.btn{border:0;border-radius:9px;padding:11px 15px;background:#315ee7;color:#fff;font-weight:800;cursor:pointer}.btn.secondary{background:#fff;color:#315ee7;border:1px solid #d8dfeb}.btn.danger{background:#fff0f0;color:#a22f2f;border:1px solid #ffd3d3}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:13px;border-bottom:1px solid #edf0f5;text-align:left;font-size:14px}.table th{font-size:11px;color:#6e788a;text-transform:uppercase}.modal{display:none;position:fixed;inset:0;background:#0006;align-items:center;justify-content:center;padding:20px}.modal.show{display:flex}.dialog{width:min(520px,100%);background:#fff;border-radius:16px;padding:24px}.field{margin:12px 0}.field label{display:block;font-size:12px;font-weight:800;margin-bottom:6px}.success{background:#ebf9f1;color:#176a3c;padding:11px;border-radius:9px;margin-bottom:14px}.actions{display:flex;gap:7px;align-items:center}.link{color:#315ee7;text-decoration:none;font-weight:750}@media(max-width:700px){.bar{flex-direction:column;align-items:stretch}.table{min-width:850px}.card{overflow:auto}}</style></head><body><header class="top"><strong>SPS CRM · Clients</strong><a href="dashboard.php">← Dashboard</a></header><main class="wrap"><?php if($message):?><div class="success"><?=e($message)?></div><?php endif;?><div class="bar"><div><h1>Clients</h1><div>Search, inspect, archive and create client records.</div></div><button class="btn" onclick="openModal()">+ Add Client</button></div><div class="card"><form class="search" method="get"><input class="input" name="q" value="<?=e($search)?>" placeholder="Search name, email or code"><button class="btn secondary">Search</button></form><table class="table"><thead><tr><th>Code</th><th>Client</th><th>Contact</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($clients as $c):?><tr><td><?=e($c['client_code'])?></td><td><strong><?=e($c['first_name'].' '.$c['last_name'])?></strong></td><td><?=e($c['email']?:'—')?> <?=e($c['phone']?:'')?></td><td><?=status_badge($c['status'])?></td><td><?=e($c['created_at'])?></td><td><div class="actions"><a class="link" href="client_profile.php?id=<?=(int)$c['id']?>">View</a><form method="post" onsubmit="return confirm('Archive this client?')"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=(int)$c['id']?>"><button class="btn danger">Archive</button></form></div></td></tr><?php endforeach;?><?php if(!$clients):?><tr><td colspan="6">No clients found.</td></tr><?php endif;?></tbody></table></div></main><div id="modal" class="modal"><div class="dialog"><h2>Add Client</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><div class="field"><label>First Name</label><input name="first_name" required></div><div class="field"><label>Last Name</label><input name="last_name" required></div><div class="field"><label>Email</label><input type="email" name="email"></div><div class="field"><label>Phone</label><input name="phone"></div><div style="display:flex;justify-content:flex-end;gap:8px"><button type="button" class="btn secondary" onclick="closeModal()">Cancel</button><button class="btn">Create Client</button></div></form></div></div><script>function openModal(){document.getElementById('modal').classList.add('show')}function closeModal(){document.getElementById('modal').classList.remove('show')}</script></body></html>
